#pragma once
static void guidanceTests(Window &w,const QString &output,std::function<void(QString,bool)> check){
 auto reset=[&]{w.model=Model::example();w.history.clear();w.selectionIds.clear();w.selection.clear();w.uml=false;w.en=false;w.mode=1;w.applyTheme();w.buildMenus();w.refresh();w.fit();qApp->processEvents();};
 reset();auto original=w.model.json();auto point=w.view->mapFromScene(w.nodes["contiene"]->scenePos());QMouseEvent press(QEvent::MouseButtonPress,point,w.view->viewport()->mapToGlobal(point),Qt::LeftButton,Qt::LeftButton,Qt::NoModifier),release(QEvent::MouseButtonRelease,point,w.view->viewport()->mapToGlobal(point),Qt::LeftButton,Qt::NoButton,Qt::NoModifier);QApplication::sendEvent(w.view->viewport(),&press);QApplication::sendEvent(w.view->viewport(),&release);
 check("Mouse selection shows A and B on relationship endpoints",w.roleBadges.size()==2&&w.roleBadges[0]->role=="A"&&w.roleBadges[0]->parentItem()==w.nodes["ordine"]&&w.roleBadges[1]->role=="B"&&w.roleBadges[1]->parentItem()==w.nodes["riga"]);
 check("Role badges do not alter model or undo history",w.model.json()==original&&w.history.isClean());
 check("Badges are anchored at upper left without covering entity names",w.roleBadges.size()==2&&w.roleBadges[0]->pos()==QPointF(-w.nodes["ordine"]->size.width()/2,-w.nodes["ordine"]->size.height()/2-25));
 qApp->processEvents();w.grab().save(output+"/roles-chen.png");
 QImage image(28,28,QImage::Format_ARGB32);image.fill(Qt::white);{QPainter p(&image);p.translate(2,2);w.roleBadges[0]->paint(&p,nullptr,nullptr);}check("Badge uses yellow fill and ruby border",image.pixelColor(5,5)==QColor("#ffeb3b")&&image.pixelColor(2,10)==QColor("#9b111e"));image.save(output+"/badge-A.png");
 QString error;check("Export with role selection succeeds",w.exportPdf(output+"/roles-clean.pdf",QPageSize::A4,true,true,error));check("PDF export restores live role badges",w.roleBadges.size()==2&&!w.printing&&w.selection=="contiene");
 w.selectOnly("ordine");check("Changing selection hides role badges",w.roleBadges.isEmpty());check("Reference export without badges succeeds",w.exportPdf(output+"/roles-reference.pdf",QPageSize::A4,true,true,error));
 w.selectOnly("contiene");w.pick("ordine",2);check("Multiple selection hides ambiguous role hints",w.roleBadges.isEmpty());w.selectOnly("contiene");w.uml=true;w.refresh();check("UML view retains correct role hints",w.roleBadges.size()==2&&w.roleBadges[0]->parentItem()==w.nodes["ordine"]);w.fit();qApp->processEvents();w.grab().save(output+"/roles-uml.png");
 w.model.get("contiene")->a="riga";w.model.get("contiene")->identifying=false;w.refresh();check("Recursive relationship shows adjacent A and B on same entity",w.roleBadges.size()==2&&w.roleBadges[0]->parentItem()==w.roleBadges[1]->parentItem()&&w.roleBadges[1]->pos()-w.roleBadges[0]->pos()==QPointF(28,0));qApp->processEvents();w.grab().save(output+"/roles-recursive.png");
 reset();check("Copyright stays in the upper menu area",w.menus->isAncestorOf(w.credit)&&!w.statusBar()->isAncestorOf(w.credit)&&w.credit->text().contains("https://infotechlab.altervista.org"));
 check("Native title contains application name once",!w.windowFlags().testFlag(Qt::FramelessWindowHint)&&w.windowTitle().count("Database Schema Studio")==1);
 check("Copyright is aligned to menu right",w.menus->cornerWidget(Qt::TopRightCorner)->isAncestorOf(w.credit));
 w.showMaximized();qApp->processEvents();check("Native window maximize works",w.isMaximized());w.showNormal();qApp->processEvents();check("Native window restore works",!w.isMaximized());
 check("Workflow is accessible in toolbar and Help",w.findChild<QAction*>("workflowToolbar")&&w.findChild<QAction*>("workflowAction"));
 {QScopedPointer<QDialog> dialog(w.workflowDialog());dialog->show();qApp->processEvents();auto browser=dialog->findChild<QTextBrowser*>("workflowText");check("Italian workflow explains the three modeling steps",browser&&browser->toPlainText().contains("1 · Descrivi la situazione")&&browser->toPlainText().contains("2 · Trasforma il modello")&&browser->toPlainText().contains("3 · Prepara il codice SQL"));dialog->grab().save(output+"/workflow-italiano.png");dialog->close();}
 w.en=true;w.buildMenus();w.refresh();{QScopedPointer<QDialog> dialog(w.workflowDialog());dialog->show();qApp->processEvents();auto browser=dialog->findChild<QTextBrowser*>("workflowText");check("English workflow explains the steps and supported SQL engines",browser&&browser->toPlainText().contains("2 · Turn the model into tables")&&browser->toPlainText().contains("HSQLDB 1.8, MySQL 8.4 or MariaDB 10.11"));dialog->grab().save(output+"/workflow-english.png");dialog->close();}
 for(bool english:{false,true}){w.en=english;auto before=w.model.json();QScopedPointer<QDialog> dialog(w.workflowDialog());dialog->show();qApp->processEvents();auto browser=dialog->findChild<QTextBrowser*>("workflowText");browser->verticalScrollBar()->setValue(browser->verticalScrollBar()->maximum());qApp->processEvents();check("Workflow final instructions remain reachable in both languages",browser->verticalScrollBar()->value()==browser->verticalScrollBar()->maximum()&&browser->toPlainText().contains(english?"Save your work":"Salva il lavoro")&&w.model.json()==before);dialog->grab().save(output+QString("/workflow-end-%1.png").arg(english?"en":"it"));}
 reset();w.selectOnly("contiene");
}
